class DOMUtils{static escapeHtml(e){const t=document.createElement("div");return t.textContent=e,t.innerHTML}static createElement(e,t="",r=""){const n=document.createElement(e);return t&&(n.className=t),r&&(n.innerHTML=r),n}static insertBefore(e,t){return!(!t||!t.parentNode)&&(t.parentNode.insertBefore(e,t),!0)}static removeAll(e){const t=document.querySelectorAll(e);return t.forEach(e=>e.remove()),t.length}static addListener(e,t,r){return e.addEventListener(t,r),()=>e.removeEventListener(t,r)}}export{DOMUtils as D};
